) AS (
  VALUES 
    (729::BIGINT, 'Pide muchas cosas, el curso en sí es fácil de pasar. No es la mejor, pero es meh.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-07-02T00:00:00+00:00'::TIMESTAMPTZ, '64cd94fb22d7af37995c727ff58368b775256f27ee6daaaa558d1329935a749d'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Es estricta con las evaluaciones y carece mucho de simpatía, pero el curso es gratis. Nunca falte a clase, sino pierde muchos puntos. Sólo pide que prendan la cámara en las evaluaciones. No es mala opción, pero definitivamente no es la mejor.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2022-05-11T00:00:00+00:00'::TIMESTAMPTZ, 'f341855d9d2b6543730bfb34c828d61853292c0b9ba552df8f38de95bd5d54e6'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Pesima de profesora, nunca llevaría otro curso con ella, muy pedante, arrogante y no se actualiza, explica horrible, definitivamente la peor profesora que he conocido.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2022-04-28T00:00:00+00:00'::TIMESTAMPTZ, '012b458404701872c54cc5449af8c6d36967fa05d66bd903a299a71795472ab8'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Pésima, desordenada y explica mal.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-02-01T00:00:00+00:00'::TIMESTAMPTZ, '8fef0b256f3bb9401dc269aa47f48225233cd54deb16eda2ffe67dcfd7501aa7'::TEXT, ARRAY[263]::BIGINT[]),
    (729::BIGINT, 'Es una buena profe, sin embargo tiene un modo un poco amargado, yo no disfrutaba sus clases, si puede matricular con alguien mejor, hágalo.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'd6f3f1e571377aedcff40831b4fae4af17b4c86ab9a3dc58ee709d6b8db217d7'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Se enreda para explicar y se le hace un ocho el administrar los grupos a los que imparte clases La asistencia con ella importa y califica bastante duro'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2021-12-17T00:00:00+00:00'::TIMESTAMPTZ, 'b4ad44c627b79a9aebc7ee34f689f01207e5bf2b8c5bf36675cd0564d0197fc5'::TEXT, ARRAY[556]::BIGINT[]),
    (729::BIGINT, 'Los trabajos los califica bien, hasta llega a ayudar un poco. De igual manera con las exposiciones, sin embargo, da buena retroalimentación. Puede durar un poco a la hora de revisar trabajos. Cámara y participación obligatoria.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2021-12-17T00:00:00+00:00'::TIMESTAMPTZ, 'c1b6c526e4a1e4b7dfc5ee86ce480860c4180f7a3bd14d88a3fa27ee3e197dcb'::TEXT, ARRAY[556]::BIGINT[]),
    (729::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-10-25T00:00:00+00:00'::TIMESTAMPTZ, 'b3be47a3ebca9f1e9727ce2f1b466fd7b93818c4c97829dff6c6734d7d42b276'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2021-07-13T00:00:00+00:00'::TIMESTAMPTZ, 'b44459493076429c7b3d6f25d7cb3f9ff698f6205ad1f07757a6a6f874c1f907'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Si una hace todo como se debe la profe no se va a poner en varas. Tiene un mal caracter en muchas ocasiones pero pasar el curso es bastante sencillo si se asiste a clase y se realizan los trabajos. Como es virtual pone a hacer videos y al final una presentacion por zoom con compañeros.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, '54f7208ce861d0780a83f351900271be308fc8724731932eac03fecaa19e0abb'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Ella no es mala persona, pero quiere que todo se haga como ella quiere aunque este en contra del reglamento, pide que enciendan la cámara toda la clase y es muy grosera. Para un curso de un crédito creo que hay mejores. Hace una guía didáctica que ayuda mucho en los trabajos.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'c805d2d70eae23ca89c2845d001cbae8f8e49bebf1e2cf0f18ee5f57e04ddd61'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Es un hp curso de un crédito, debería dejar de joder tanto, no pido que regale el curso pero sí que entienda que con malas caras, carga extra y siendo una berrinchuda no va lograr nada en el estudiante y no es mi deber aguantarle todo solo porque "esto es el TEC"'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'a75373d506dc4e9beafea31f568ea632c0e27cd589009c73fd9c34fc06d404d3'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Es grosera con los estudiantes.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-05-27T00:00:00+00:00'::TIMESTAMPTZ, '23c32c1bfa01064bc811c02d04df6dd6152d60d216a0ed042e074a11fb95a527'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Es muy tediosa, desconsiderada con los estudiantes con internet limitado por su manía de ver las cámaras encendidas aún cuando la persona no está hablando, cuando le preguntan algo se enoja, parece que siempre está de mal humor, no cae a la razón que el curso es de 1 solo crédito, se excede del tiem'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2021-04-27T00:00:00+00:00'::TIMESTAMPTZ, '1b414a375ef3b869c4aac66511e345305f20745ead364a353eb5b897f77d256b'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'clases demasiado largas, aburridas, es my grosera con todos y obliga a encender la cámara a pesar de que no es permitido, no le importa la condición de otros solo quiere que todo sea como ella quiere'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2021-03-22T00:00:00+00:00'::TIMESTAMPTZ, 'e031a9f5f3b957c6bee38015da5b2153128261cc67fba8c25d6eb01747e9eb31'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Llevé con ella en modalidad virtual. Es super ordenada y dedicada a su trabajo, las notas de las evaluaciones que deja las lleva al día en el TEC Digital. Es estricta, pero las evaluaciones son sencillas y personalmente, aprendí muchísimo del curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '7b2aa53ca0bfed67497e748a495acc51c178cc2e58a20b33eb52bdbd66243355'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Es algo desordenada, las evaluaciones no son muy pesadas, no califica duro; sin embargo, es cierto que sí le preguntas algo probablemente te responda de una forma tosca y se enoje. Es difícil conseguir ayuda extra y que le resuelva dudas con respuestas concretas. Se pasa fácil y se aprende algo.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'be49cd5236c996083681f225c96c5189c9d907d74b70425c90513e3ce94c49d3'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'El curso es sencillo, a pesar de ser virtual se aprende un montón, en especial a como realizar buenas exposiciones. Se aprende bastante. La profesora lo organiza muy bien, deja una cantidad moderada de evaluaciones. Las clases son cortas y no son pesadas. Recomendada para el curso.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, '4f5b4a6d73edb53a5eccbb337ad427cf56711d9776b5a19aff79a588635d60be'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'La profe es algo estricta, pero el curso es fácil. De fijo llevaría este tipo de cursos con ella. La recomiendo si no se quiere joder mucho. Olguita es un amor si usted es cumplidor.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-13T00:00:00+00:00'::TIMESTAMPTZ, '62c5ccb79fb21a44f2cbf6be7f5ad6d3502fa6096568475848f25dc11ce72f1a'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-19T00:00:00+00:00'::TIMESTAMPTZ, 'fed726be34fe70a936b0ef2659a355bd99a56462c11cf9dcbaa03425cb6adc03'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Con las clases virtuales, se adaptó bien, utilizando clases asincronicas. No deja un montón de trabajos, el curso se pasa fácil, si se van realizando los trabajos que deja. Tal vez no es la mejor profesora, pero podría volver a tomar otro curso virtual con ella.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '755acf1f9aa61f27325bca62aa8c663a99166d6ad0192ea6366e9c94fcda62eb'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'La profesora es algo estricta, sus clases son un toque desordenadas sin embargo el curso es llevadero y fácil de pasar. Ademas suele dar puntos extra por asistir a algunas actividades.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Da crédito extra']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '9871b601a77f6d6ff316bf589ced4d83e3e94667c69f45a98798f30c6735e468'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Muy enredada, sí se le preguntaba algo se enojaba y lo mandaba a leer el pdf y ahí tenía que estar la respuesta El curso en sí fue fácil pero enredado'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'cd41ea6f0fc59f78c272f0268eedf9b09b8f7ee4f19164286b96e96afefd0ce5'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Pésima profesora, se enoja con todo mundo y por nada, no apoya en absolutamente nada, no explica bien, no ayuda en horas fuera de clase por ningún motivo, no se entiende ni las clases ni las asignaciones, y si preguntan algo se enoja'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'f5ceaac7c1018cdc8a2de9447a557b9aaa2dbf7873c2782397db245c6b522902'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Tarde bastante en contestar correos, como atiende diferentes grupos, se enreda mucho y pasa estresada.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, 'd27f4bffcf228e86d6bc514ebcbbd3e6da5772a2d0331b2d7a5ad045f623a7ff'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Buena profesora, pero mucho desorden con los documentos en el TEC Digital'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '4425a469052f0649a8c4893ff3151420f86e7c5ea26e33de593193948ac365e5'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Cambió las fechas en 3 ocasiones, las indicaciones para sus trabajos eran ambiguas y se enojaba si uno le preguntaba algo, duró 3 semanas para contestar mensajes sobre dudas de una nota; una pésima profesora y persona, si pueden evitarla, mejor!'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '8be35d8f9bda0cd946c434a955cc168d7763ce0222dda9c73d5bf2fd230404a4'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'La modalidad virtual es genial para este curso, la mayoría de clases son asincrónicas, solo tienes que acostumbrarte a grabarte con una cámara y ella califica muy suavemente, además te ahorras viajes a Cartago para ver obras.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Da crédito extra']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'f42dca26607c227e67b39af4251073331a25a06dbc067e894a08bc7a599a3612'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Le grita a los estudiantes, no los deja opinar mucho, pero es facil pasar'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-11T00:00:00+00:00'::TIMESTAMPTZ, 'd2c0d0c837bd1a65e4cb4e4e4b821264421636b9ae67c07d97fac9905787aea1'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Es buena, califica suave, solo que hay que hacer todo a la manera de ella y seguir lo que ella indica. Realmente es buena profe y llevaría oral con ella. En modalidad virtual es buena, lo malo es si te toca con una mierda de compañeros nada mas xd'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'd0080711b3a7ae9eef2acbec13448430b635d78b0be309527193b0078caa0101'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Es muy desordenada al dar la clase y son bastante pesadas. Pero si asiste a todas las clases el curso se pasa solo.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '39ffb4f8fc4609be299c83d85066e5390d6d5ce2042063d4db244afb91131537'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2020-08-05T00:00:00+00:00'::TIMESTAMPTZ, '4c1475a0e8149413631ae98cb4e5c3d4a3814432d29c537cd95628a7c4d4c978'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Es demasiado aburrida, trata como de humillar a los estudiantes y en cuestiones de ayuda en hora de consulta se pone enojada si le haces alguna pregunta, casi no le gusta aclarar la materia simplemente te manda a leer, la verdad no la recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'd9a113f3838f4af6f3d38b95129a8c66881879fd15ca8cac25a88bd9e24a1028'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Fácil pasar con ella. A veces se pone necia, pero simplemente es acatar lo que ella pide al exponer cada semana'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Da crédito extra']::TEXT[], '2020-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'f619c648bac5b5e24949cb783fa0f2d9abd4198932f54eb1bd2f73d14855830f'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'La clase es aburrida, bastante, pero no es muy dura calificando, solo hay que hablar claro en las exposiciones y no ver el suelo para pasar con 8+'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Pocos exámenes']::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, '50ec2b98d375244ea36f559d641bc9ee7bf2c65e965549c818d142ad52639865'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'El curso es aburrido, pero con ella se pasa fácil. No deja muchas tareas, y califica suave mientras no llegue a hacer el papel exponiendo. No se preocupa por la vestimenta. Buena profesora.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-27T00:00:00+00:00'::TIMESTAMPTZ, '6c2886d8c7abffdd4c4cbb850d3548e842eb7437c5466ee476e4f5185d5e3dc2'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Al principio debes de exponer mucho y sin previo aviso. Siempre tiene cara de que lo que dices no tiene sentido pero ella es así en general, califica suave y es muy fácil pasar el curso. Es una profe normal.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros']::TEXT[], '2019-11-16T00:00:00+00:00'::TIMESTAMPTZ, '5ece5ae2cf233cdf90f3d51cfad6aa61299fa03d6560bb819d18a9bfc15a8143'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Muy fácil con ella, recomendado.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-12T00:00:00+00:00'::TIMESTAMPTZ, '20df4756eb2bc503957bb2733c7cc6a929771087282e2c23f954418fcbf36972'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Su clase es aburrida a mas no poder, pero no es culpa de ella, en general este curso es una basura en donde no se aprende porque la catedra plantea el curso de forma mediocre. Al final la señora calificar super facil'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Muchos proyectos grupales']::TEXT[], '2019-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'a416c8aea4faf73ec28819c3ed6efac7b23b7091274b43fcffed93648f3325bc'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Es una profe buena si se toma en cuenta que es un curso introductorio. Si usted le pone atención y hace los trabajos como tiene que ser y le agarra interés, créame que no va a tener ningún problema, va a aprender y va a pasar el curso fácilmente.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-07-09T00:00:00+00:00'::TIMESTAMPTZ, '1cbab623d699c3e9f474d07acf25a262c0c824e345dce8431904e6129ebe9105'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'ab77379e523ad5d5fec70a960f9d88ce48fb6f017506d4f4dd9099c44fd016a0'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'No califica duro,pero hay que poner de nuestra parte y realizar los trabajos recomendada'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, '1c6f4ac67a74e97513f9e8de0842de19589dcb212a29830c80dd5ae9ab149839'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'No se le entiende nada, es muy desorganizada, las instrucciones nunca son claras, pide cosas que nunca menciono antes, su manera de calificar es muy tonta, no tiene criterios buenos de calificación, las clases son aburridas, pero al final se pasa facil'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'e12442996f83a2e8743fb37e39526e16e9cab3e23122d048c8648d3bbef3a552'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'b6e450cb6e17169c479eb02559eb1f4893ff2dc5b80ce39c5a7cd52194997a2e'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'La verdad es de esos profesores con los que uno realmente no aprende nada, pero se pasa fácil si uno hace los tres millones de trabajos que deja'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2019-03-26T00:00:00+00:00'::TIMESTAMPTZ, 'ecdac9f91dc8de837f486c431c658d0884721145c9982a9c40194c46ebfacb0a'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Pésima profesora, no sabe hablar y tiene aires de que sabe mucho y todo lo que dice está en internet. Además desmotiva solo el hecho de su presentación personal'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-03-12T00:00:00+00:00'::TIMESTAMPTZ, '2f4696d8df35f493665215a828804b5e4db4659e2240e0668ea72b5bfc93b765'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Muy mala no deja en claro las instrucciones y deja trabajos muy largos. Señora existen más cursos además del suyo.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2019-03-03T00:00:00+00:00'::TIMESTAMPTZ, '2061548e28f540d59d6d0f12767ccc03a2c3b27dac64672d5e69a60807988c6b'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'No sabe nada es una profesora de wikipedia si matricula con ella perderá su tiempo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-02-28T00:00:00+00:00'::TIMESTAMPTZ, '714f39a4f41f3145000557c767d6954b9d9c037d53427ec4171516296d809263'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Las clases son super aburridas. Si usted lleva muchos cursos no matricule con ella, deja tareas super largas y quita tiempo.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2019-02-26T00:00:00+00:00'::TIMESTAMPTZ, '8d342c006398d13bee63d9ffde2e6d08df535c0e120aedba6213174689dee90c'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'No pide vestimenta formal para las presentaciones. Entiende a los estudiantes. Sin embargo su forma de evaluar es cuestionable. Califica según lo que logra percibir en el momento. En general buena profesora'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-16T00:00:00+00:00'::TIMESTAMPTZ, '93d1f144e940fd53001f3785d47367f7e44f5f2844e1937c649cd5b36786b723'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Muy buena profesora, se pasa fácil'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-05T00:00:00+00:00'::TIMESTAMPTZ, '5e577ca16bbd3f44ddfba0cc359a8bc2442ff725b90ab9c2329a2f3a78407bc3'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'La clase es aburrida pero muy fácil, realice todos los talleres y pasa con más de 90. No pide vestimenta formal'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'a89917e33bdfa5e7968e66e374e641d3f70fed390283569ba06d04b2dfb5a2c6'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Ella la clase la da pero en algunos casos no queda del todo claro, pero se entiende solo porque en si la materia es facil. Ni le pida ayuda, usualmente le sale con que es su responsabilidad bla bla bla. Pero la clase si es super facil si hace todo los trabajos y presenta todo'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-22T00:00:00+00:00'::TIMESTAMPTZ, '6e7bccbfe4454728c021a3315015b723e4a37566d368949bc4144d3d9d3ccb8e'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Buena profe, compresiva y trabajos acordes. Además no exige vestimenta formal para exposiciones, de las pocas que no exige'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-04T00:00:00+00:00'::TIMESTAMPTZ, 'f47e1466b59194f1003ea2c39a551db556554a095c902f044f4b8b134658a5c9'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-10-24T00:00:00+00:00'::TIMESTAMPTZ, 'c634e316c90a62b52c841be067eb9b46a70805a8cf1dd489f214b860e923b98a'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'En general es una buena profesora. Las clases son muy repetitivas (Instrucciones-Taller- Exposicion). Preparese para leer un montón. Tenga paciencia y de lo mejor de si, de fijo pasa con mas de 90.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, '21d1a0c6b70ac1d12c312e834f36ebc5f10a3729f15caa5b1886f6d9c57f9ec8'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Es muy sencillo con ella, quizá si sea algo desordenada, pero si usted cumple con todo pasa minimo con 90 jaja'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'a7b52b27b0883a3519f6f15dc42405db154107fa634f5b4fa9e4c03f1a94d08e'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '25028a5570f1cff3b2942765a31c034a1873527535b4990868b63bfb5c53e185'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'El curso se pasa fácil. Los talleres se hacen en clase y son muy sencillos. No hay exámenes, solo trabajos. La clase es bastante relajada. Casi todo se hace en grupo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'eb43e344047b2751afe494732abc40e5589a9f804bb59c3cbdaaea11bc4a1cfa'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Se pasa con solo hacer los talleres aunque a veces quitan tiempo fuera de clase.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'a8c546f1fa01b41c3fc17ed974b47aeec3aa90f5ca62b0e1d8273765991d5f97'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Califica suave, las clases son aburridas,se pasa facil'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'd6228f3ab77bdef079acf445b0d7c62f3c51605fa94a2ea2854f141d347f027f'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Dejó el curso en semana 10 y dijo que no podía seguir pero no por qué... En fin, es muy llevadera, se pasa casi con sólo ir a clases porque hace talleres. Con ir a los ciclos de exposición se asegura pasar sin los exámenes. Aveces se confunde con las fechas pero si todos están al día no hay problema'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes']::TEXT[], '2018-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'd05b649c6e0b907b44f6ca2b3b3515dc60af4b6320f7af575433feeff2dc22d5'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-07T00:00:00+00:00'::TIMESTAMPTZ, '16182239f6c1c30d782f6b32e1c7ee1a0763cf930fb54f3179a71130ab3443f1'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'ella es muy confusa para dar indicaciones, generalmente no se le entiende. Ademas deja trabajos por afuera y quitan tiempillo'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-04-20T00:00:00+00:00'::TIMESTAMPTZ, '87738ac02229642dda53ff2618bb444deec589f27fc112b43475f5e02de30b60'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Sus clases se basan en hacer talleres, los cuales son muy sencillos. Sin embargo no es muy clara en las instrucciones, siempre quedan dudas y es necesario pedirle que las aclare una vez más'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-03-09T00:00:00+00:00'::TIMESTAMPTZ, 'c62e7ca9ef74654159331071182b189cb70c5959960e6a0802d9db3e3966e5b9'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Deja muchos talleres para ser de 1 crédito pero son fáciles; casi todas las clases tienen entregas o talleres. Las clases magistrales son muy aburridas (de cabecear) pero se aprende. NUNCA pasen lista si llega tarde, se enojará mucho; será muy estricta y poco llevadera después de eso.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'b37488c1044b199d9b4c93a34fcdbb7b698a02db86f83eaf785598fd93f09f50'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Califica super suave, se aprende y se pasa SUPER FACIL. En casi todas las clases hay exposiciones pero con que uno las haga ya es un 100 asegurado. Las exposiciones de 25% son fáciles porque califica suave y no exige llegar con vestimenta formal. Recomendada :D'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, '7f7db5887d010ef29eff0eb83de5a43ecdc57735e1a78acb63d343e2ecdb2734'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Todas las clases se hace una exposición, sin embargo es algo sencillo y máximo 2 minutos. Todas las clases hay taller que técnicamente es hacerlo o subir el archivo y se tiene 100. Se pasa muy fácil, explica lo necesario.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'b0507bdb121d72748c811ead6e494816ad65bd515ba2d7098b97efcb4bd3835a'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'c3e243a92f23c8bdf5a3963c034236f3063cac9d412d08749fce7498d88cd2cd'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Es buena profesora, un poco desordenada, pero se aprende bastante y no consume mucho tiempo sus clases. La recomiendo :)'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'c970cb18ed5a3faa28fc509f882be4e172ed3949ac4c2e28d335424168664c60'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Se pasa fácil, con solo hacer los talleres 25%, ir al ciclo de exposiciones y hacer los trabajos para puntos extra. Es un poco desordenada, califica suave pero se aprende y siempre esta dispuesta a ayudar.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-15T00:00:00+00:00'::TIMESTAMPTZ, '1134b35e60aad4f6b2f1f5bcdf0eaf0eb093000d2d3486e5600870219fa37d85'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Para un curso de 1 crédito deja demasiados trabajos y se gasta en promedio 4 horas por semana que uno podría estar usando para otros cursos más pesados. En realidad uno no aprende nada en este curso y parece estar más de relleno que otra cosa.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-09-26T00:00:00+00:00'::TIMESTAMPTZ, '658231d63bff9537d916102060674f74ad7813c3e64a54a0553f4ec93f653f0e'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Muy fácil de pasar, aunque las instrucciones son confusas se aprende algo...pero las clases se le van a hacer las mas largas de la vida. Y sin afán de ofender ella tiene una voz que molesta mucho.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'ef6d30ef189512bbdfdda1e0e59d6fc529fc4ae803cd1519b5f8a90d5c3837f5'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Las clases son aburridas pero califica muy suave'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '2395d630b65119e0e19ee1283a488a31bdba48ff9d4ae4a636e16b1e57f9b9ca'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Es agradable y suele dar buenas notas a todo, lo único malo es que a veces no es muy clara con las indicaciones de los trabajos y la materia no es muy interesante entonces cansa mucho'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'b5916ddcdba1ae1176bf9ca796b7090733bf91e905316a83f57e769c279d9377'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2017-05-16T00:00:00+00:00'::TIMESTAMPTZ, '8a30acf53c957cf186649156cb1047d60231cf12589b848faa90559901532109'::TEXT, ARRAY[556]::BIGINT[]),
    (729::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2017-05-16T00:00:00+00:00'::TIMESTAMPTZ, 'aad97c7d66adb20e0f0552e7b2293bcf870643b1c48cf51448816ee1650d3f84'::TEXT, ARRAY[556]::BIGINT[]),
    (729::BIGINT, 'Pésima profesora. No tiene nivel de Universidad más bien parece una orientador de Cole'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-05-11T00:00:00+00:00'::TIMESTAMPTZ, 'a8ebac5fc0aa83a68c9e3cf94b099e01691ca17c9776b370e19904e05e70d108'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Excelente profesora, hace un taller por clase para prácticar y califica lo normal, a veces se le olvidan las indicaciones o las fechas de los trabajos, pero es muy comprensiva. 100% RECOMENDADA'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'ab9e1b56d4dac478251f1f26a6d85a76c4c9f969f44d56ecfab05e33419693e0'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Se pasa fácil; simplemente haga los talleres y buenas exposiciones y listo. Se aprende bastante'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'f7e1b42a0cab3f81889707ef04e0a1f29507163e03998a726045c95e0a9dd1b3'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Buena gente, pero no la recomiendo. Clases muy largas y aburridas. Las indicaciones de los trabajos que se asignaban no eran muy claras, siempre había confusion en clase.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2016-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'd0641531f0528039fbe98368181e0b9435d736295a2c78064dee2380831c611e'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Deja muchos trabajos, tiene una voz chillona y habla mucho, muy exigente,'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'dc0c819811fc60849944798d1fe5f2f93c78c1cfbf28d68c2368497ab4ecd9d8'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Deja pocos trabajos, pero no explica casi que nada, es una clase muy aburrida y siempre anda de mal humor, lo compensa porque se pasa muy fácil'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'b4b0e0e97fe88cc867a9195c3c11f8c5b85f233cd9439deb9808f58a7800c7ba'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'es facil, no deja muchas tareas'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'e1f159fcfc7689e2b9c374367fa3a9742c421e483d945c433b746ce22339e850'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'NO LA LLEVE CON ELLA'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '28c5539e42335dd8a76d6ed850ef9da35707333ac1f7ce1d94ad0239ff662bc1'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Llega tarde, no deja las cosas claras y es algo desordenada. Y te hace el curso algo pesadillo. Pero no le veo complicaciones para aprobar.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura']::TEXT[], '2016-05-08T00:00:00+00:00'::TIMESTAMPTZ, 'ef02ad1fa57a5d892558154ff49a17552759529864fe19526e7b6d9a221f14ab'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-03-17T00:00:00+00:00'::TIMESTAMPTZ, '83c03be4a887cf7b2ea7f7d8a0ef3e4cc9a721d79439d00203915161ec5f5268'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Es muy buena gente, las clases las hace por talleres y eso ayuda mucho para agarrar confianza con el grupo, califica bien. Es algo desordenada porque siempre se le olvida algo y llega tarde la mayoria de veces'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-02-02T00:00:00+00:00'::TIMESTAMPTZ, '536aef43bce16257557acf65367a8918140386c43b57fe5ee1e9d9682a7ac7e7'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Algo se aprende en sus clases. Es un poco desordenada y califica normal. Sus clases son entretenidas y no deja muchos tareas.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-28T00:00:00+00:00'::TIMESTAMPTZ, '716c0a9c0793b0bdb72143528fa21c0091ad3b3466db652e689bea29a0f4a715'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'La peor profesora que he tenido. No entiendo cómo trabaja en el tec. Aparte su presentación personal es como de añeja y es poco ética, le pregunta a los estudiantes por la calidad de los cursos que reciben con sus compañeros de trabajo. Vaga, tonta y mala. Mal recomiendo..'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-06T00:00:00+00:00'::TIMESTAMPTZ, '63a6ca348f92cfe0bffb6c1b2608baeacd65a00c0e90929b8779eb767bb32e86'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'b215fe031aaf7b1890a1d241f526cb3fae0ecbff06f541af44d3baf56ea89552'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Es muy buena, es un poco despistada, pero se aprende mucho, la metodologia que usa es talleres en el LAIMI, y ahi se aprende mas, no deja tareas muy largas ni quita mucho tiempo, y se aprende bien. Aparte no califica rudo, y busca como ayudar al estudiante cuando tiene un problema con los trabajos.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-26T00:00:00+00:00'::TIMESTAMPTZ, '1cf6264ae24dac326b70de65ea93e78356d94bfa80bc0186cca2a4827c794a68'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'En realidad no la recomiendo, porque se aprende lo necesario solamente. Para vagos es genial, clase fácil y no toma mucho tiempo. Hay mejores. Si quiere salir sabiendo hacer informes, no matricule con ella. Si quiere pasar fácil, adelante.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-19T00:00:00+00:00'::TIMESTAMPTZ, '4b51f1d70992d65d81f56aeb86508bc64399ce7090d467d36f78104defac2a35'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Es muy fácil pasar. Es un poco desorganizada. Se aprende lo necesario.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'cecbf6cd0fe11f6dd2389cfd92651433eab481b73056b17baedae6915fa30794'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Para la gente que quiera pasar sin poner atención, sin entender ni aprender y sin hacer absolutamente nada...esta es la Profe indicada (y)'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-16T00:00:00+00:00'::TIMESTAMPTZ, '1f48ad885d6867a747bfa33d2219a320d8b93613ab422ad2d0550cd272a4be90'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'explica mal, pero uno aprende con las actividades en el LAIMI,'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-30T00:00:00+00:00'::TIMESTAMPTZ, '3fbf8b448e44d1170667a62ad293772c614d3b5c52955852ceba63f2cfc656fe'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Se aprende lo suficiente, se aprovecha mucho el tiempo de clases.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'e1db88cb2f5ef0a536944f2402b2c9b48c17edd1344a10a8cab84797413f3780'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Se enreda, es super buena gente todo el mundo pasa con cien y sin hacer nada, califica super suave.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '3e5827befc0ed73fcc98ed02cb9ff0da08632bf3e2f7d3865189e933e4f4d379'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Muy fácil. Algo desordenada. Explica bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'ee287f23f189b358eb7c6186aa52b22b55d342ddb7eedd1664bb27e2ea6f1c62'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Es muy buena gente, no deja tantos trabajos y ayuda al estudiante bastante'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '56dab3657764c3cbebf1e39ba4d028c36eb742c919c3cc07a5e0ccc2b7f41aa9'::TEXT, ARRAY[554]::BIGINT[]),
    (729::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'cdd00599e23bf7a4616960c12a494d05a0a4234d49d5999c061f49172ba174f1'::TEXT, ARRAY[600]::BIGINT[]),
    (729::BIGINT, 'Es un poco desordenada pero es buena gente y le ayuda a uno con el redondeo bastante!'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'f27477190149d8e88ecc1325e02b32e2f9b55481922bade7f727706a4bc36f84'::TEXT, ARRAY[600]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
